<?php
namespace App\Http\Controllers;
use App\Models\{Payment,Contact,Account,Currency,SalesInvoice,PurchaseBill};use App\Services\PaymentService;use Illuminate\Http\Request;
class PaymentController {public function index(){return view('payments.index',['payments'=>Payment::forCompany(auth()->user()->company_id)->with('contact')->latest('payment_date')->paginate(50)]);}public function create(Request $r){$c=$r->user()->company_id;$type=$r->query('type','receipt');return view('payments.create',['type'=>$type,'contacts'=>Contact::forCompany($c)->whereIn('type',$type==='receipt'?['customer','both']:['supplier','both'])->where('active',1)->get(),'cashAccounts'=>Account::forCompany($c)->where('is_postable',1)->where('active',1)->where('type','asset')->orderBy('code')->get(),'currencies'=>Currency::where('active',1)->get(),'documents'=>$type==='receipt'?SalesInvoice::forCompany($c)->where('status','posted')->whereNull('credit_of_invoice_id')->get():PurchaseBill::forCompany($c)->where('status','posted')->whereNull('credit_of_bill_id')->get()]);}public function store(Request $r){$d=$r->validate(['type'=>'required|in:receipt,supplier_payment','contact_id'=>'required|integer','payment_date'=>'required|date','currency_id'=>'required|integer','amount'=>'required|decimal:0,3','exchange_rate'=>'required|decimal:1,10','cash_account_id'=>'required|integer','allocations'=>'required|array|min:1','allocations.*.document_id'=>'required|integer','allocations.*.amount'=>'required|decimal:0,3']);$p=$d['type']==='receipt'?app(PaymentService::class)->receive($r->user()->company_id,$r->user()->id,$d,$d['allocations']):app(PaymentService::class)->paySupplier($r->user()->company_id,$r->user()->id,$d,$d['allocations']);return redirect()->route('payments.index')->with('ok','Payment posted '.$p->payment_number); }public function void(Request $r,Payment $payment){$d=$r->validate(['date'=>'required|date','reason'=>'required|string|max:1000']);app(PaymentService::class)->void($payment,$r->user()->id,$d['date'],$d['reason']);return back()->with('ok','Payment voided by reversal.');}}
